doc.codeblock:
type PromptKind string
const ( PromptKindPermission PromptKind = "permission" PromptKindQuestion PromptKind = "question" PromptKindReview PromptKind = "review" // 多题结尾的 Submit answers / Cancel 复核页 )
type OptionTone string
const ( TonePrimary OptionTone = "primary" // 第 1 项 / 推荐默认 / Submit answers ToneNeutral OptionTone = "neutral" // 本会话允许 / 持久化配置 / 普通选项 ToneDanger OptionTone = "danger" // 拒绝 / Deny / Cancel / No )
type PromptOption struct { Index int // 0-based TUI 选项索引 KeyHint string // 编号徽章，如 "1", "2", "3", "4" Label string // TUI 实时原文（或结合 JSONL 的标题） Description string // 可选副标题（来自 TUI 折行或 JSONL） Tone OptionTone // 视觉语义角色 Checked bool // 多选模式下当前勾选状态 NeedsText bool // 是否需要用户输入自定义文本（Other / Type something. / tell Claude...） InlineTextMode bool // 光标停在该行即可直接输入（Pi/Claude 为 true，无需先按 Enter） IsSubmit bool // 多选/多题流程中的显式提交行（Next / Submit answers） }
type InteractivePrompt struct { Kind PromptKind Harness string // claude / antigravity / codex / pi / omp Title string // 权限标题或当前问题题干 Detail string // 拟执行命令 / 工具摘要 / 复核摘要 Cursor int // 当前远端 TUI 高亮行索引（0-based） Options []PromptOption // 真实选项列表 MultiSelect bool // 是否为多选勾选模式 Tabs []string // 多题页签标题（如 ["Feature", "Testing", "Submit"]） ActiveTab int // 当前页签索引（0-based） CanSwitchTab bool // 是否支持 Tab/Shift+Tab 或 ←/→ 切题 Fingerprint string // 选项列表 + 标题 + 模式的规范化哈希，发送前二次核对防竞态 }
